        ':status': 200
      });
      stream.end('<h1>Server Push Example</h1><link rel="stylesheet" href="/styles.css">');
    }
    // 404 Not Found
  else {
    stream.respond({
      'content-type': 'text/plain',
      ':status': 404
    });
    stream.end('404 - Not Found');
  }
});

// Handle errors
server.on('error', (err) => {
  console.error('Server error:', err);
  process.exit(1);
});

