  input: process.stdin,
  output: process.stdout,
  prompt: 'js> '
});

// Create context for evaluating code
const context = vm.createContext({
  console,
  Number,
  String,
  Array,
  Object,
  // Add any other global variables you want to make available
  // You can also add your own functions
  add: (a, b) => a + b,
  multiply: (a, b) => a * b
});

