<script>
  import { onMount } from 'svelte';

  let todos = [];
  let loading = true;

  onMount(async () => {
    const response = await fetch('http://localhost:8080/api/todos');
    todos = await response.json();
    loading = false;
  });

  function toggleTodo(id) {
    todos = todos.map(todo => {
      if (todo.id === id) {
        return { ...todo, done: !todo.done };
      }
      return todo;
    });
  }
